import { useCallback, useEffect, useState } from "react";
import { Text } from "react-native";
import { useAuth } from "../../src/auth";
import { supabase } from "../../src/supabase";
import {
  EmptyState,
  ErrorState,
  GlassCard,
  LoadingState,
  Screen,
} from "../../src/components";
import { formatDate, titleCase } from "../../src/format";
import { shared, tokens } from "../../src/theme";
import type { AiInsightRow } from "../../src/types";

/**
 * Coach — the trader's STORED weekly insights (ai_insights,
 * generated by the deterministic Coach Engine and kept current
 * by the Phase 20 trade-close pipeline). Read-only in M2: the
 * Interactive AI Coach arrives in the next phase.
 */
export default function CoachScreen() {
  const { session } = useAuth();
  const [insights, setInsights] = useState<AiInsightRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    if (!session) return;
    setLoading(true);
    setError(null);
    const { data, error: queryError } = await supabase
      .from("ai_insights")
      .select("*")
      .eq("user_id", session.user.id)
      .order("generated_at", { ascending: false })
      .limit(20);
    if (queryError) {
      setError(queryError.message);
    } else {
      setInsights((data ?? []) as AiInsightRow[]);
    }
    setLoading(false);
  }, [session]);

  useEffect(() => {
    void load();
  }, [load]);

  if (loading) return <LoadingState label="Loading your insights…" />;

  return (
    <Screen>
      <Text style={shared.title}>Coach</Text>
      <GlassCard>
        <Text style={{ color: tokens.auroraViolet, fontWeight: "700", fontSize: 14 }}>
          Your stored weekly insights
        </Text>
        <Text style={shared.muted}>
          Interactive AI Coach arrives in the next phase — these are your stored
          weekly insights, generated from your real trades by the TraderOS Coach
          Engine.
        </Text>
      </GlassCard>
      {error ? <ErrorState message={error} /> : null}
      {!error && insights.length === 0 ? (
        <EmptyState
          title="No insights yet"
          body="Weekly insights are generated from your closed trades. Once a week has enough trades, its insights will appear here."
        />
      ) : null}
      {insights.map((insight) => (
        <GlassCard key={insight.id}>
          <Text style={shared.label}>{titleCase(insight.insight_type)}</Text>
          <Text style={shared.body}>{insight.summary}</Text>
          <Text style={shared.muted}>
            {insight.period_start && insight.period_end
              ? `${formatDate(insight.period_start)} → ${formatDate(insight.period_end)}`
              : `Generated ${formatDate(insight.generated_at)}`}
          </Text>
        </GlassCard>
      ))}
    </Screen>
  );
}
